/* Latvian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Janis": "God is gracious — Hebrew Yohanan", "Anna": "grace — Hebrew Hannah", "Peteris": "rock, stone — Greek petros", "Ilze": "God is my oath — Hebrew Elisheva", "Andris": "manly, brave — Greek Andreas", "Liga": "A feminine name from the midsummer festival.", "Berzins": "The most Latvian of surnames; feminine Berzina.", "Kalnins": "A classic diminutive surname; feminine Kalnina.", "Ozolins": "A classic diminutive surname; feminine Ozolina.", "Liepins": "A classic diminutive surname; feminine Liepina."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Janis';
console.log(lookup(q));

